has_role = frappe.db.exists("Has Role", {
    "parent": frappe.session.user,
    "role": "Timesheet Approver",
    "parenttype": "User"
})

if has_role:
    conditions = f"""
        (
            `tabTimesheet`.employee in (
                select name from `tabEmployee` where user_id = '{frappe.session.user}'
            )
            or
            `tabTimesheet`.employee in (
                select name from `tabEmployee`
                where reports_to = (
                    select name from `tabEmployee` where user_id = '{frappe.session.user}'
                )
            )
        )
    """
else:
    conditions = ""

today = frappe.utils.getdate(frappe.utils.nowdate())

weekday_map = {"Monday": 0, "Tuesday": 1, "Wednesday": 2, "Thursday": 3,
               "Friday": 4, "Saturday": 5, "Sunday": 6}
month_names = ["January", "February", "March", "April", "May", "June",
               "July", "August", "September", "October", "November", "December"]

def get_next_occurrence(todo, today):
    repeat_type = (todo.custom_repeat or "").strip().lower()

    if repeat_type == "daily":
        return today

    if repeat_type == "weekly":
        if not todo.custom_repeat_on:
            return None
        target_wd = weekday_map.get(todo.custom_repeat_on.strip())
        if target_wd is None:
            return None
        days_ahead = (target_wd - today.weekday()) % 7
        return frappe.utils.add_days(today, days_ahead)

    if repeat_type == "monthly":
        day = todo.custom_day_of_month
        if not day and todo.custom_start_date:
            day = frappe.utils.getdate(todo.custom_start_date).day
        if not day:
            return None
        try:
            occurrence = today.replace(day=int(day))
        except ValueError:
            return None
        if occurrence < today:
            next_month = today.month % 12 + 1
            next_year = today.year + (1 if today.month == 12 else 0)
            try:
                occurrence = today.replace(year=next_year, month=next_month, day=int(day))
            except ValueError:
                return None
        return occurrence

    if repeat_type == "yearly":
        if not todo.custom_month or not todo.custom_day:
            return None
        month_num = month_names.index(todo.custom_month.strip()) + 1
        try:
            occurrence = today.replace(month=month_num, day=int(todo.custom_day))
        except ValueError:
            return None
        if occurrence < today:
            occurrence = occurrence.replace(year=occurrence.year + 1)
        return occurrence

    return None


closed_todos = frappe.get_all(
    "ToDo",
    filters={
        "status": "Closed",
        "custom_repeat": ["not in", ["", "Does Not Repeat"]],
    },
    fields=[
        "name",
        "custom_repeat",
        "custom_repeat_daily",
        "custom_repeat_on",
        "custom_day_of_month",
        "custom_month",
        "custom_day",
        "custom_start_date",
        "custom_show_before",
        "custom_last_completed_for",
    ],
)

for todo in closed_todos:
    should_reopen = False
    occurrence = None

    if todo.custom_repeat_daily:
        occurrence = today
        should_reopen = True
    else:
        occurrence = get_next_occurrence(todo, today)
        if occurrence:
            try:
                show_before = int(todo.custom_show_before or 0)
            except (ValueError, TypeError):
                show_before = 0
            window_start = frappe.utils.add_days(occurrence, -show_before)
            if window_start <= today <= occurrence:
                should_reopen = True

    if should_reopen and occurrence:
        already_completed = (
            todo.custom_last_completed_for
            and frappe.utils.getdate(todo.custom_last_completed_for) == occurrence
        )
        if not already_completed:
            frappe.db.set_value("ToDo", todo.name, "status", "Open")

frappe.db.commit()

if doc.status == "Closed" and doc.custom_repeat and doc.custom_repeat not in ["", "Does Not Repeat"]:
    today = frappe.utils.getdate(frappe.utils.nowdate())

    weekday_map = {"Monday": 0, "Tuesday": 1, "Wednesday": 2, "Thursday": 3,
                   "Friday": 4, "Saturday": 5, "Sunday": 6}
    month_names = ["January", "February", "March", "April", "May", "June",
                   "July", "August", "September", "October", "November", "December"]

    repeat_type = (doc.custom_repeat or "").strip().lower()
    occurrence = None

    if repeat_type == "daily" or doc.custom_repeat_daily:
        occurrence = today

    elif repeat_type == "weekly":
        if doc.custom_repeat_on:
            target_wd = weekday_map.get(doc.custom_repeat_on.strip())
            if target_wd is not None:
                days_ahead = (target_wd - today.weekday()) % 7
                occurrence = frappe.utils.add_days(today, days_ahead)

    elif repeat_type == "monthly":
        day = doc.custom_day_of_month
        if not day and doc.custom_start_date:
            day = frappe.utils.getdate(doc.custom_start_date).day
        if day:
            try:
                occurrence = today.replace(day=int(day))
                if occurrence < today:
                    next_month = today.month % 12 + 1
                    next_year = today.year + (1 if today.month == 12 else 0)
                    occurrence = today.replace(year=next_year, month=next_month, day=int(day))
            except ValueError:
                occurrence = None

    elif repeat_type == "yearly":
        if doc.custom_month and doc.custom_day:
            month_num = month_names.index(doc.custom_month.strip()) + 1
            try:
                occurrence = today.replace(month=month_num, day=int(doc.custom_day))
                if occurrence < today:
                    occurrence = occurrence.replace(year=occurrence.year + 1)
            except ValueError:
                occurrence = None

    if occurrence:
        doc.custom_last_completed_for = occurrence
